arguments.query:
-- Step 1: Find the start event of python.exe by cmd.exe
SELECT time, pid, ppid, pname, process_name, command_line, parent_process_name, parent_command_line
FROM audit_logs
WHERE pname = 'cmd.exe' AND pid IN (
  SELECT ppid FROM audit_logs WHERE pname = 'python.exe'
) AND EXISTS (
  SELECT 1 FROM audit_logs WHERE pname = 'python.exe' AND ppid = audit_logs.pid
)
ORDER BY time LIMIT 10;

SELECT time, pid, ppid, pname, process_name, command_line, parent_process_name, parent_command_line
FROM audit_logs
WHERE pname = 'cmd.exe' AND pid IN (
  SELECT DISTINCT ppid FROM audit_logs WHERE pname = 'python.exe'
)
ORDER BY time LIMIT 10;
